s: 1rem; color: #fff; }\\n  .rag-green { background: var(--green); } .rag-amber { background: var(--amber); } .rag-red { background: var(--red); }\\n  .tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));\\n           gap: .6rem; list-style: none; padding: 0; }\\n  .tiles li { border: 1px solid var(--line); border-radius: .4rem; padding: .6rem .75rem; background: var(--bg); }\\n  .tiles h3 { margin: 0; font-size: .82rem; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); }\\n  .tiles p { margin: .35rem 0 0; font-weight: 600; }\\n  meter { width: 100%; height: .9rem; }\\n  dl.meta { display: grid; grid-template-columns: max-content 1fr; gap: .25rem 1rem; margin: 1rem 0 0; }\\n  dl.meta dt { font-weight: 600; color: var(--muted); }\\n  dl.meta dd { margin: 0; }\\n  footer { margin-top: 3rem; border-top: 1px solid var(--line); padding-top: .75rem;\\n           font-size: .82rem; color: var(--muted); }\\n  /* ==== Print: A4/Letter safe, no split rows/tiles ==== */\\n  @media print {\\n    body { max-width: none; padding: 0; font-size: 10.5pt; }\\n    section, table, .tiles li { break-inside: avoid; }\\n    h2 { break-after: avoid; }\\n    a { text-decoration: none; color: inherit; }\\n    .placeholder { background: none; outline: none; }\\n  }\\n</style>\\n</head>\\n<body>\\n\\n<header>\\n  <!-- EDIT: project identity -->\\n  <h1>[PROJECT NAME] — Status Report</h1>\\n  <p class=\\\"lede\\\">Report #[N] of [TOTAL] &middot; Period: <time datetime=\\\"[YYYY-MM-DD]\\\">[start]</time> to <time datetime=\\\"[YYYY-MM-DD]\\\">[end]</time></p>\\n  <dl class=\\\"meta\\\">\\n    <dt>Issued</dt><dd><time datetime=\\\"[YYYY-MM-DD]\\\">[issue date]</time></dd>\\n    <dt>Author</dt><dd>[name, role] — <address style=\\\"display:inline\\\">[email]</address></dd>\\n    <dt>Sponsor</dt><dd>[sponsor name]</dd>\\n    <dt>Distribution</dt><dd>[audience list]</dd>\\n    <dt>Classification</dt><dd>[e.g., Internal]</dd>\\n  </dl>\\n</header>\\n\