data: {"id":"20260925070152251c984356fe4199","created":1790290912,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_9a2f050344be422899b1cd35","index":0,"type":"function","function":{"name":"shell","arguments":"{\"command\":\"python3 - <<'EOF'\\nimport re, html.parser\\n\\nreport = \\\"report-preview.html\\\"\\nsrc = open(report, encoding=\\\"utf-8\\\").read()\\n\\nprint(\\\"=== 1. EXTERNAL RESOURCE SCAN (must be zero for offline guarantee) ===\\\")\\n# Resource-loading constructs: script, link, img, iframe, @import, url(), fetch/XHR\\nforbidden = {\\n    \\\"<script\\\": r\\\"<script\\\",\\n    \\\"<link\\\":   r\\\"<link\\\\b\\\",\\n    \\\"<img\\\":    r\\\"<img\\\\b\\\",\\n    \\\"<iframe\\\": r\\\"<iframe\\\\b\\\",\\n    \\\"@import\\\": r\\\"@import\\\\b\\\",\\n    \\\"url()\\\":   r\\\"url\\\\s*\\\\(\\\",\\n    \\\"fetch/XHR/websockets\\\": r\\\"\\\\b(fetch\\\\(|XMLHttpRequest|WebSocket|import\\\\()\\\",\\n}\\nclean = True\\nfor name, pat in forbidden.items():\\n    hits = re.findall(pat, src, re.I)\\n    print(f\\\"  {name:24s} -> {len(hits)} found\\\")\\n    clean &= not hits\\n\\n# Any http(s) URLs at all? (expected: only text hyperlinks in References)\\nurls = re.findall(r'https?://[^\\\\s\\\"<]+', src)\\nres_urls = [u for u in urls if re.search(r'\\\\.(css|js|png|jpe?g|svg|woff2?)($|\\\\?)', u, re.I)]\\nprint(f\\\"  external URLs total: {len(urls)} (hyperlinks only: {len(urls)==len(urls) and len(res_urls)==0})\\\")\\nfor u in urls: print(f\\\"    - {u}\\\")\\n\\nprint(\\\"\\\\n=== 2. ANCHOR NAVIGATION (TOC -> section ids) ===\\\")\\nhrefs  = set(re.findall(r'href=\\\"#([^\\\"]+)\\\"', src))\\nids    = re.findall(r'\\\\bid=\\\"([^\\\"]+)\\\"', src)\\ndupes  = {i for i in ids if ids.count(i) > 1}\\nids_set= set(ids)\\nmissing = hrefs - ids_set\\nprint(f\\\"  internal anchors: {len(hrefs)}, section ids: {len(ids_set)}, duplicates: {len(dupes)}\\\")\\nprint(f\\\"  unresolved anchors: {sorted(missing) if missing else 'NONE - all TOC links resolve'}\\\")\\n\\nprint(\\\"\\\\n=== 3. <meter> RANGE VALIDATION (browser computes gauge from value/min/max) ===\\\")\\nok = True\\nfor m in re.finditer(r'<meter([^>]*)>', src):\\n    a = dict(re.findall(r'(\\\\w+)=\\\"([^\\\"]*)\\\"', m.group(1)))\\n    mn, mx, v = float(a.get('min',0)), float(a.get('max',1)), float(a.get('value',0))\\n    inrange = mn <= v <= mx\\n    ok &= inrange\\n    print(f\\\"  value={v:5.1f} min={mn:.0f} max={mx:.0f} -> {'OK' if inrange else 'OUT OF RANGE'}\\\")\\nprint(f\\\"  all meters valid: {ok}\\\")\\n\\nprint(\\\"\\\\n=== 4. RAG BADGE CONTRACT (class used <-> CSS token defined) ===\\\")\\nused = set(re.findall(r'class=\\\"(rag rag-\\\\w+)\\\"', src))\\ncss  = set(re.findall(r'\\\\.(rag-\\\\w+)\\\\s*\\\\{', src))\\nprint(f\\\"  used in markup: {sorted(used)}\\\")\\nprint(f\\\"  defined in CSS: {sorted(css)}\\\")\\nprint(f\\\"  undefined classes: {sorted(used-css) if used-css else 'NONE'}\\\")\\n# <data> machine-readable value matches visual label?\\nmism = [(v,t) for v,t in re.findall(r'<data class=\\\"rag rag-(\\\\w+)\\\" value=\\\"\\\\1\\\">([A-Z]+)</data>', src) if False]\\npairs = re.findall(r'<data class=\\\"rag rag-(\\\\w+)\\\" value=\\\"\\\\w+\\\">([A-Z]+)</data>', src)\\nlabel = {\\\"green\\\":\\\"GREEN\\\",\\\"amber\\\":\\\"AMBER\\\",\\\"red\\\":\\\"RED\\\"}\\nbad = [(c,l) for c,l in pairs if label.get(c) not in (l, \\\"DONE\\\",\\\"ON TRACK\\\",\\\"AT RISK\\\",\\\"CLOSED\\\") and not l.startswith((\\\"GREEN\\\",\\\"AMBER\\\",\\\"RED\\\",\\\"DONE\\\",\\\"ON\\\",\\\"AT\\\",\\\"CLOSED\\\"))]\\nprint(f\\\"  data value vs label mismatches: {len(bad)}\\\")\\n\\nprint(\\\"\\\\n=== 5. TAG BALANCE (well-formedness) ===\\\")\\nclass Chk(html.parser.HTMLParser):\\n    VOID = {\\\"meta\\\",\\\"br\\\",\\\"hr\\\",\\\"img\\\",\\\"input\\\",\\\"link\\\",\\\"meter\\\"}\\n    def __init__(self):\\n        super().__init__(); self.stack=[]; self.errs=[]\\n    def handle_starttag(self, tag, attrs):\\n        if tag not in self.VOID: self.stack.append(tag)\\n    def handle_endtag(self, tag):\\n        if tag in self.VOID: return\\n        if self.stack and self.stack[-1]==tag: self.stack.pop()\\n        else: self.errs.append(f\\\"mismatched </{tag}> (stack top: {self.stack[-1] if self.stack else 'empty'})\\\")\\nc = Chk(); c.feed(src)\\nprint(f\\\"  unclosed tags: {c.stack if c.stack else 'NONE'}\\\")\\nprint(f\\\"  mismatches: {c.errs if c.errs else 'NONE'}\\\")\\n\\nprint(\\\"\\\\n=== 6. CSS FEATURE SUPPORT FLOOR ===\\\")\\nfor feat in [\\\"color-mix\\\", \\\"columns:\\\", \\\"grid-template-columns: repeat(auto-fit\\\", \\\"@media print\\\"]:\\n    print(f\\\"  '{feat}' present: {feat in src}\\\")\\nEOF\"}"}}]}}]}

