   Layers: 1 tokens · 2 base · 3 layout · 4 components · 5 utilities · 6 print
   ============================================================ */
:root {
  --paper:   #ffffff;
  --ink:     #1a2332;
  --muted:   #56677c;
  --line:    #d7dee8;
  --surface: #f4f6f9;
  --accent:  #1f4e79;
  --ok:      #2e7d32;
  --warn:    #9a5b00;
